mapper.select:
select entity_id
from kg_entity
where entity_type = #{entityType}
  and external_key = #{externalKey}

select relation_id
from kg_relation
where source_entity_id = #{sourceEntityId}
  and relation_type = #{relationType}
  and target_entity_id = #{targetEntityId}

select entity_id entityId, entity_type entityType, external_key externalKey, canonical_name canonicalName, normalized_name normalizedName, properties_json propertiesJson, review_status reviewStatus, ontology_version ontologyVersion, create_time createTime, update_time updateTime from kg_entity where entity_id in
#{entityId}
order by entity_id

select r.relation_id relationId, r.relation_type relationType, r.source_entity_id sourceEntityId, se.entity_type sourceEntityType, se.canonical_name sourceEntityName, r.target_entity_id targetEntityId, te.entity_type targetEntityType, te.canonical_name targetEntityName, r.confidence, r.valid_from validFrom, r.valid_to validTo, r.review_status reviewStatus, r.ontology_version ontologyVersion, r.source_kind sourceKind, r.properties_json propertiesJson from kg_relation r join kg_entity se on se.entity_id = r.source_entity_id join kg_entity te on te.entity_id = r.target_entity_id where r.review_status <> 'REJECTED' and (r.valid_to is null or r.valid_to > sysdate()) and ( r.source_entity_id in
#{entityId}
or r.target_entity_id in
#{entityId}
) order by r.relation_id

select evidence_id evidenceId, evidence_key evidenceKey, relation_id relationId, entity_id entityId, source_type sourceType, source_ref sourceRef, material_id materialId, page_no pageNo, char_start charStart, char_end charEnd, quote_hash quoteHash, excerpt, confidence, extractor_version extractorVersion, create_time createTime from kg_evidence where relation_id in
#{relationId}
order by relation_id, evidence_id

select evidence_id evidenceId, evidence_key evidenceKey, relation_id relationId, entity_id entityId, source_type sourceType, source_ref sourceRef, material_id materialId, page_no pageNo, char_start charStart, char_end charEnd, quote_hash quoteHash, excerpt, confidence, extractor_version extractorVersion, create_time createTime from kg_evidence where entity_id in
#{entityId}
order by entity_id, evidence_id

mapper.delete:
delete ev
from kg_evidence ev
where ev.material_id = #{materialId}
  and ev.source_ref like concat('material:', #{materialId}, ':dimension:%');

delete from kg_entity
where entity_type = 'CapabilityAssessment'
  and external_key like concat('assessment:', #{materialId}, ':%');
